(function(){
  'use strict';
  const NS='http://www.w3.org/2000/svg';
  const project=p=>({x:(p.lng+180)*3,y:(85-p.lat)*3.15});
  const unproject=p=>({lng:Math.max(-180,Math.min(180,p.x/3-180)),lat:Math.max(-60,Math.min(85,85-p.y/3.15))});
  let worldPaths='';
  for(const country of window.GEO_WORLD){let d='';for(const ring of country.rings){let prev=null;for(const [lng,lat] of ring){const p=project({lng,lat});d+=!prev||Math.abs(p.x-prev.x)>540?`M${p.x.toFixed(1)},${p.y.toFixed(1)}`:`L${p.x.toFixed(1)},${p.y.toFixed(1)}`;prev=p;}d+='Z';}worldPaths+=`<path d="${d}"/>`;}
  class AtlasMap{
    constructor(host,{onPick=null,hero=false}={}){
      this.host=host;this.onPick=onPick;this.hero=hero;this.locked=false;this.pointers=new Map();this.box={x:0,y:0,w:1080,h:500};this.abort=new AbortController();this.guess=null;this.answer=null;
      host.innerHTML=`<svg class="world-svg" viewBox="0 0 1080 500" aria-label="世界地图，拖动移动，滚轮或双指缩放。方向键移动，回车在地图中心选点。" ${hero?'aria-hidden="true"':'tabindex="0" role="application"'}><defs><pattern id="grid-${hero?'hero':'play'}" width="90" height="63" patternUnits="userSpaceOnUse"><path d="M90 0H0V63" fill="none" stroke="#81927e" stroke-opacity=".09" stroke-width=".7"/></pattern><radialGradient id="land-light"><stop stop-color="#53633c"/><stop offset="1" stop-color="#293629"/></radialGradient></defs><rect x="0" y="0" width="1080" height="500" fill="url(#grid-${hero?'hero':'play'})"/><g class="countries">${worldPaths}</g><path class="equator" d="M0 ${project({lng:0,lat:0}).y}H1080"/><g class="map-labels"><text x="190" y="135">北 美 洲</text><text x="339" y="350">南 美 洲</text><text x="566" y="110">欧 洲</text><text x="575" y="270">非 洲</text><text x="795" y="143">亚 洲</text><text x="945" y="395">大 洋 洲</text></g><g class="map-overlay"></g></svg>${hero?'':`<div class="map-region-controls"><button data-region="world" class="selected">世界</button><button data-region="europe">欧洲</button><button data-region="asia">亚洲</button><button data-region="america">美洲</button></div><div class="map-zoom-controls"><button data-zoom="in" aria-label="放大地图">＋</button><button data-zoom="out" aria-label="缩小地图">−</button><button data-zoom="reset" aria-label="重置地图">⌖</button></div><span class="map-attribution">地图数据：Natural Earth · 城市中心计分</span><div class="map-center" aria-hidden="true">＋</div>`}`;
      this.svg=host.querySelector('svg');this.overlay=host.querySelector('.map-overlay');this.resizeObserver=new ResizeObserver(()=>this.draw());this.resizeObserver.observe(host);
      if(hero){this.drawHero();return;}
      const opts={signal:this.abort.signal};
      this.svg.addEventListener('pointerdown',e=>this.down(e),opts);
      this.svg.addEventListener('pointermove',e=>this.move(e),opts);
      this.svg.addEventListener('pointerup',e=>this.up(e),opts);
      this.svg.addEventListener('pointercancel',e=>{this.pointers.delete(e.pointerId);this.dragged=true;this.gesture=null;},opts);
      this.svg.addEventListener('wheel',e=>{e.preventDefault();this.zoom(Math.exp(-e.deltaY*.002),this.point(e));},{...opts,passive:false});
      this.svg.addEventListener('keydown',e=>{const steps={ArrowLeft:[-1,0],ArrowRight:[1,0],ArrowUp:[0,-1],ArrowDown:[0,1]};if(steps[e.key]){e.preventDefault();const [x,y]=steps[e.key];this.box.x+=x*this.box.w*.07;this.box.y+=y*this.box.h*.07;this.update();}else if(['+','=','-','Enter',' '].includes(e.key)){e.preventDefault();if(e.key==='Enter'||e.key===' '){if(!this.locked)this.onPick?.(unproject({x:this.box.x+this.box.w/2,y:this.box.y+this.box.h/2}));}else this.zoom(e.key==='-'?.7:1.4);}},opts);
      host.querySelectorAll('[data-zoom]').forEach(b=>b.addEventListener('click',()=>b.dataset.zoom==='reset'?this.region('world'):this.zoom(b.dataset.zoom==='in'?1.6:1/1.6),opts));
      host.querySelectorAll('[data-region]').forEach(b=>b.addEventListener('click',()=>this.region(b.dataset.region),opts));
    }
    point(e){const p=new DOMPoint(e.clientX,e.clientY);return p.matrixTransform(this.svg.getScreenCTM().inverse());}
    down(e){if(e.button!==0)return;this.svg.setPointerCapture(e.pointerId);this.pointers.set(e.pointerId,{x:e.clientX,y:e.clientY});this.start={x:e.clientX,y:e.clientY};this.dragged=false;if(this.pointers.size>1){this.dragged=true;this.gesture=this.pinch();}}
    pinch(){const [a,b]=[...this.pointers.values()];return a&&b?{d:Math.hypot(a.x-b.x,a.y-b.y),x:(a.x+b.x)/2,y:(a.y+b.y)/2}:null;}
    move(e){if(!this.pointers.has(e.pointerId))return;const prev=this.pointers.get(e.pointerId);this.pointers.set(e.pointerId,{x:e.clientX,y:e.clientY});if(this.pointers.size>1){this.dragged=true;const next=this.pinch();if(this.gesture&&next&&this.gesture.d>0)this.zoom(next.d/this.gesture.d,this.point({clientX:next.x,clientY:next.y}));this.gesture=next;return;}if(Math.hypot(e.clientX-this.start.x,e.clientY-this.start.y)>5)this.dragged=true;if(this.dragged){const a=this.point({clientX:prev.x,clientY:prev.y}),b=this.point(e);this.box.x-=b.x-a.x;this.box.y-=b.y-a.y;this.update();}}
    up(e){if(!this.pointers.has(e.pointerId))return;const eligible=!this.dragged&&this.pointers.size===1;this.pointers.delete(e.pointerId);this.gesture=null;if(this.pointers.size===1){const p=[...this.pointers.values()][0];this.start=p;this.dragged=true;}if(eligible&&!this.locked){const p=this.point(e);if(p.x>=0&&p.x<=1080&&p.y>=0&&p.y<=457)this.onPick?.(unproject(p));}}
    zoom(factor,p={x:this.box.x+this.box.w/2,y:this.box.y+this.box.h/2}){const w=Math.min(1080,Math.max(60,this.box.w/factor)),h=w*500/1080;this.box={x:p.x-(p.x-this.box.x)*w/this.box.w,y:p.y-(p.y-this.box.y)*h/this.box.h,w,h};this.update();}
    region(name){const b={world:[0,0,1080,500],europe:[470,65,230,106.5],asia:[715,75,330,152.8],america:[65,75,330,152.8]}[name];this.box={x:b[0],y:b[1],w:b[2],h:b[3]};this.host.querySelectorAll('[data-region]').forEach(e=>e.classList.toggle('selected',e.dataset.region===name));this.update();}
    update(){this.box.x=Math.max(0,Math.min(1080-this.box.w,this.box.x));this.box.y=Math.max(0,Math.min(500-this.box.h,this.box.y));this.svg.setAttribute('viewBox',`${this.box.x} ${this.box.y} ${this.box.w} ${this.box.h}`);this.draw();}
    setPoints(guess,answer=null){this.guess=guess;this.answer=answer;this.locked=!!answer;this.draw();}
    reveal(guess,answer){this.setPoints(guess,answer);const a=project(guess),b=project(answer),w=Math.min(1080,Math.max(175,Math.abs(a.x-b.x)*1.8,Math.abs(a.y-b.y)*3.3));this.box={x:(a.x+b.x-w)/2,y:(a.y+b.y-w*500/1080)/2,w,h:w*500/1080};this.update();}
    marker(p,color,label){const a=project(p),s=1/(this.svg.getScreenCTM()?.a||1);return `<g transform="translate(${a.x} ${a.y}) scale(${s})"><circle r="18" fill="${color}" fill-opacity=".1"/><circle r="10" fill="${color}" fill-opacity=".16"/><circle r="4.5" fill="${color}" stroke="#151b16" stroke-width="2"/><text y="-24" text-anchor="middle" fill="${color}" font-size="13" font-weight="600" paint-order="stroke" stroke="#101911" stroke-width="4">${label}</text></g>`;}
    draw(){if(!this.overlay||this.hero)return;let out='';if(this.guess&&this.answer){const a=project(this.guess),b=project(this.answer);out=`<path d="M${a.x} ${a.y} Q${(a.x+b.x)/2} ${Math.min(a.y,b.y)-Math.abs(a.x-b.x)*.16} ${b.x} ${b.y}" fill="none" stroke="#d4f975" stroke-width="1.5" stroke-dasharray="5 5" vector-effect="non-scaling-stroke"/>`;}if(this.guess)out+=this.marker(this.guess,'#b9bfff',this.answer?'你的选择':'待锁定');if(this.answer)out+=this.marker(this.answer,'#d4f975',this.answer.city);this.overlay.innerHTML=out;}
    drawHero(){const cities=[{lng:-71,lat:42,name:'BOSTON'},{lng:2.35,lat:48.85,name:'PARIS'},{lng:126.98,lat:37.56,name:'SEOUL'},{lng:121.47,lat:31.23,name:'SHANGHAI'},{lng:-43.17,lat:-22.9,name:'RIO'}];let out='';for(const p of cities){const a=project(p);out+=`<g class="hero-point"><circle cx="${a.x}" cy="${a.y}" r="13" fill="#d4f975" opacity=".06"/><circle cx="${a.x}" cy="${a.y}" r="3" fill="#d4f975"/><text x="${a.x+10}" y="${a.y-9}">${p.name}</text></g>`;}const a=project(cities[1]),b=project(cities[2]);out+=`<path d="M${a.x} ${a.y} Q${(a.x+b.x)/2} -25 ${b.x} ${b.y}" fill="none" stroke="#d4f975" stroke-opacity=".55" stroke-width="1.2" stroke-dasharray="4 7"/>`;this.overlay.innerHTML=out;}
    destroy(){this.abort.abort();this.resizeObserver?.disconnect();}
  }
  window.AtlasMap=AtlasMap;
})();
